194	// tracedDo performs a request while recording the interim (1xx) statuses
195	// observed on the client connection, in arrival order, along with the time at
196	// which the first interim status arrived (relative to the request start).
197	func tracedDo(t *testing.T, client *http.Client, req *http.Request) (*http.Response, []int, time.Duration) {
198		t.Helper()
199		var (
200			mu             sync.Mutex
201			interim        []int
202			firstInterimAt time.Duration
203		)
204		start := time.Now()
205		trace := &httptrace.ClientTrace{
206			Got1xxResponse: func(code int, _ textproto.MIMEHeader) error {
207				mu.Lock()
208				if len(interim) == 0 {
209					firstInterimAt = time.Since(start)
210				}
211				interim = append(interim, code)
212				mu.Unlock()
213				return nil
214			},
215		}
216		resp, err := client.Do(req.WithContext(httptrace.WithClientTrace(req.Context(), trace)))
217		if err != nil {
218			t.Fatalf("request %s failed: %v", req.URL.Path, err)
219		}
220		mu.Lock()
221		got := append([]int(nil), interim...)
222		at := firstInterimAt
223		mu.Unlock()
224		return resp, got, at
225	}
