227	func newFailoverClient() *http.Client {
228		dialer := &net.Dialer{Timeout: 5 * time.Second}
229		return &http.Client{
230			Timeout: 30 * time.Second,
231			Transport: &http.Transport{
232				DialContext:        dialer.DialContext,
233				DisableCompression: true,
234			},
235		}
236	}
